r.srcdoc="<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <style>\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    html, body { width: 100%; height: 100%; overflow: hidden; background: #0a0a1f; }\n    #canvas-container {\n      position: fixed; top: 0; left: 0; width: 100%; height: 100%;\n      background: radial-gradient(ellipse at center top, #1a1a3e 0%, #0a0a1f 50%, #000000 100%);\n    }\n  </style>\n</head>\n<body>\n  <div id=\"canvas-container\"></div>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n  <script>\n    let scene, camera, renderer;\n    let emotionSphere, galaxyParticles, backgroundStars;\n    let mouseX = 0, mouseY = 0;\n    let targetMouseX = 0, targetMouseY = 0;\n\n    function init() {\n      scene = new THREE.Scene();\n      scene.fog = new THREE.FogExp2(0x0a0a1f, 0.0003);\n\n      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 2000);\n      camera.position.z = 600;\n\n      renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });\n      renderer.setSize(window.innerWidth, window.innerHeight);\n      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n      document.getElementById('canvas-container').appendChild(renderer.domElement);\n\n      createBackgroundStars();\n      createEmotionSphere();\n      createGalaxyParticles();\n\n      scene.add(new THREE.AmbientLight(0xa8a2ff, 0.3));\n      const pointLight = new THREE.PointLight(0xa8a2ff, 1, 1000);\n      pointLight.position.set(0, 0, 300);\n      scene.add(pointLight);\n\n      // Mouse/touch disabled \u2014 controlled by Flutter\n\n      window.addEventListener('resize', () => {\n        camera.aspect = window.innerWidth / window.innerHeight;\n        camera.updateProjectionMatrix();\n        renderer.setSize(window.innerWidth, window.innerHeight);\n      });\n\n      animate();\n    }\n\n    function createBackgroundStars() {\n      const geo = new THREE.BufferGeometry();\n      const verts = [], cols = [];\n      for (let i = 0; i < 3000; i++) {\n        verts.push(\n          THREE.MathUtils.randFloatSpread(2000),\n          THREE.MathUtils.randFloatSpread(2000),\n          THREE.MathUtils.randFloatSpread(2000)\n        );\n        const c = new THREE.Color();\n        c.setHSL(0.7 + Math.random() * 0.1, 0.6, 0.5 + Math.random() * 0.3);\n        cols.push(c.r, c.g, c.b);\n      }\n      geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));\n      geo.setAttribute('color',    new THREE.Float32BufferAttribute(cols, 3));\n      backgroundStars = new THREE.Points(geo, new THREE.PointsMaterial({\n        size: 1.5, vertexColors: true, transparent: true,\n        opacity: 0.8, blending: THREE.AdditiveBlending\n      }));\n      scene.add(backgroundStars);\n    }\n\n    function createEmotionSphere() {\n      const count = 1000, pts = [];\n      for (let i = 0; i < count; i++) {\n        const phi   = Math.acos(-1 + (2 * i) / count);\n        const theta = Math.sqrt(count * Math.PI) * phi;\n        pts.push(\n          150 * Math.cos(theta) * Math.sin(phi),\n          150 * Math.sin(theta) * Math.sin(phi),\n          150 * Math.cos(phi)\n        );\n      }\n      const geo = new THREE.BufferGeometry();\n      geo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));\n      emotionSphere = new THREE.Points(geo, new THREE.PointsMaterial({\n        color: 0xa8a2ff, size: 2.5, transparent: true,\n        opacity: 0.7, blending: THREE.AdditiveBlending\n      }));\n      emotionSphere.position.y = -100;\n      scene.add(emotionSphere);\n    }\n\n    function createGalaxyParticles() {\n      const geo = new THREE.BufferGeometry();\n      const verts = [], cols = [];\n      for (let i = 0; i < 2000; i++) {\n        verts.push(\n          THREE.MathUtils.randFloatSpread(1500),\n          THREE.MathUtils.randFloatSpread(1500),\n          THREE.MathUtils.randFloatSpread(1500)\n        );\n        const c = new THREE.Color();\n        c.setHSL(0.65 + Math.random() * 0.15, 0.7, 0.6);\n        cols.push(c.r, c.g, c.b);\n      }\n      geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));\n      geo.setAttribute('color',    new THREE.Float32BufferAttribute(cols, 3));\n      galaxyParticles = new THREE.Points(geo, new THREE.PointsMaterial({\n        size: 2, vertexColors: true, transparent: true,\n        opacity: 0.6, blending: THREE.AdditiveBlending\n      }));\n      scene.add(galaxyParticles);\n    }\n\n    function animate() {\n      requestAnimationFrame(animate);\n      mouseX += (targetMouseX - mouseX) * 0.05;\n      mouseY += (targetMouseY - mouseY) * 0.05;\n\n      if (backgroundStars) {\n        backgroundStars.rotation.y += 0.0002;\n        backgroundStars.rotation.x += 0.0001;\n      }\n      if (emotionSphere) {\n        emotionSphere.rotation.y += 0.001;\n        emotionSphere.rotation.x  = mouseY * 0.3;\n        emotionSphere.position.x  = mouseX * 50;\n      }\n      if (galaxyParticles) {\n        galaxyParticles.rotation.y  += 0.0003;\n        galaxyParticles.position.x   = mouseX * 30;\n        galaxyParticles.position.y   = mouseY * 30;\n      }\n      renderer.render(scene, camera);\n    }\n\n    init();\n  </script>\n</body>\n</html>\n"
